const input = $input.first().json;
const data = input.body || input;
const run = data.run || { runId: 'unknown', mode: 'manual', dryRun: false };
const url = String(data.url || '').trim();
const topic = String(data.topic || '').trim();
console.log('Agent 2: run', run.runId, run.dryRun ? '(DRY RUN)' : '', '| topic:', topic || '(from page title)', '| url:', url || '-');
return [{ json: { topic, url, style: data.style, length: data.length, angle: data.angle,
  searchQuery: topic || url, hasSourceUrl: /^https?:\/\//.test(url), chosenBecause: data.chosenBecause || '', run } }];

const html = $input.first().json.data || $input.first().json || '';
const parseData = $("Parse Input").first().json;

// Convert HTML to plain text
function htmlToText(html) {
  if (typeof html !== 'string') return '';

  let text = html;

  // Remove script and style tags with content
  text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  text = text.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
  text = text.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '');
  text = text.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '');

  // Replace common block elements with newlines
  text = text.replace(/<\/(p|div|h[1-6]|li|tr|br)[^>]*>/gi, '\n');
  text = text.replace(/<br[^>]*>/gi, '\n');

  // Remove all remaining HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Decode HTML entities
  text = text.replace(/&nbsp;/g, ' ');
  text = text.replace(/&amp;/g, '&');
  text = text.replace(/&lt;/g, '<');
  text = text.replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");

  // Clean up whitespace
  text = text.replace(/\s+/g, ' ');
  text = text.replace(/\n\s*\n/g, '\n\n');
  text = text.trim();

  // Limit length to avoid token limits
  if (text.length > 8000) {
    text = text.substring(0, 8000) + '...';
  }

  return text;
}

const sourceContent = htmlToText(html);
// URL-only topics (e.g. a bare link sent to the inbox) take their title from the page.
let pageTitle = '';
if (typeof html === 'string') { const m = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i); if (m) pageTitle = m[1].replace(/\s+/g, ' ').replace(/&amp;/g, '&').trim().slice(0, 200); }
if (!parseData.topic || /^https?:/.test(parseData.topic)) { parseData.topic = pageTitle || parseData.topic; parseData.searchQuery = parseData.topic; }
console.log('✅ Agent 2: Extracted', sourceContent.length, 'chars from source URL');

return [{
  json: {
    ...parseData,
    sourceContent: sourceContent,
    sourceUrl: parseData.url
  }
}];

// No source URL, just pass through with empty sourceContent
const parseData = $("Parse Input").first().json;

return [{
  json: {
    ...parseData,
    sourceContent: '',
    sourceUrl: ''
  }
}];

const inputData = $input.first().json;
const serpResults = Array.isArray(inputData.organic_results) ? inputData.organic_results : [];
if (inputData.error) console.log('Agent 2: SerpApi failed after retries, continuing with the source page only:', String(inputData.error.message || inputData.error).slice(0, 200));

// Get source data from whichever path executed
let sourceData;
try {
  sourceData = $("Extract Source Content").first()?.json;
} catch(e) {
  sourceData = null;
}
if (!sourceData) {
  try {
    sourceData = $("No Source Content").first()?.json;
  } catch(e) {
    sourceData = $("Parse Input").first().json;
  }
}

const sources = [];
const snippets = [];
const urlsToFetch = [];

for (let i = 0; i < Math.min(serpResults.length, 5); i++) {
  const result = serpResults[i];
  if (result.link && result.title) {
    sources.push({
      url: result.link,
      title: result.title
    });
    // Only fetch top 3 for deeper content
    if (i < 3 && result.link) {
      urlsToFetch.push(result.link);
    }
  }
  if (result.snippet) {
    snippets.push(`${result.title}: ${result.snippet}`);
  }
}

console.log('✅ Agent 2: Found', sources.length, 'sources,', urlsToFetch.length, 'to fetch deeply');

return [{
  json: {
    sources: sources,
    snippets: snippets,
    urlsToFetch: urlsToFetch,
    topic: sourceData.topic,
    style: sourceData.style,
    length: sourceData.length,
    angle: sourceData.angle,
    sourceContent: sourceData.sourceContent || '',
    sourceUrl: sourceData.sourceUrl || '',
    run: sourceData.run
  }
}];

// Split URLs for fetching
const data = $input.first().json;
const urls = data.urlsToFetch || [];

if (urls.length === 0) {
  // No URLs to fetch, pass through with empty fetchedContent
  return [{
    json: {
      ...data,
      fetchedContent: [],
      hasUrlsToFetch: false
    }
  }];
}

// Return each URL as separate item for fetching
return urls.map((url, index) => ({
  json: {
    urlToFetch: url,
    urlIndex: index,
    originalData: data,
    hasUrlsToFetch: true
  }
}));

const items = $input.all();
const splitData = $("Split URLs to Fetch").all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const html = item.json.data || (typeof item.json === 'string' ? item.json : '') || '';
  const urlData = splitData[i]?.json || {};
  const urlToFetch = urlData.urlToFetch || '';

  // Convert HTML to plain text
  function htmlToText(html) {
    if (typeof html !== 'string') return '';

    let text = html;

    // Remove script and style tags with content
    text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
    text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
    text = text.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
    text = text.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '');
    text = text.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '');

    // Replace common block elements with newlines
    text = text.replace(/<\/(p|div|h[1-6]|li|tr|br)[^>]*>/gi, '\n');
    text = text.replace(/<br[^>]*>/gi, '\n');

    // Remove all remaining HTML tags
    text = text.replace(/<[^>]+>/g, ' ');

    // Decode HTML entities
    text = text.replace(/&nbsp;/g, ' ');
    text = text.replace(/&amp;/g, '&');
    text = text.replace(/&lt;/g, '<');
    text = text.replace(/&gt;/g, '>');
    text = text.replace(/&quot;/g, '"');
    text = text.replace(/&#39;/g, "'");

    // Clean up whitespace
    text = text.replace(/\s+/g, ' ');
    text = text.replace(/\n\s*\n/g, '\n\n');
    text = text.trim();

    // Limit length
    if (text.length > 3000) {
      text = text.substring(0, 3000) + '...';
    }

    return text;
  }

  const content = htmlToText(html);
  if (content.length > 100) {
    results.push({
      url: urlToFetch,
      content: content
    });
  }
}

const originalData = splitData[0]?.json?.originalData || {};

console.log('✅ Agent 2: Fetched content from', results.length, 'URLs');

return [{
  json: {
    fetchedContent: results,
    sources: originalData.sources || [],
    snippets: originalData.snippets || [],
    topic: originalData.topic,
    style: originalData.style,
    length: originalData.length,
    angle: originalData.angle,
    sourceContent: originalData.sourceContent || '',
    sourceUrl: originalData.sourceUrl || '',
    run: originalData.run
  }
}];

// No URLs to fetch path - just pass through
const data = $input.first().json;

return [{
  json: {
    fetchedContent: [],
    sources: data.sources || [],
    snippets: data.snippets || [],
    topic: data.topic,
    style: data.style,
    length: data.length,
    angle: data.angle,
    sourceContent: data.sourceContent || '',
    sourceUrl: data.sourceUrl || '',
    run: data.run
  }
}];

let data = null;
if ($('Extract Fetched Content').isExecuted) data = $('Extract Fetched Content').first().json;
if ((!data || !data.topic) && $('No URLs to Fetch').isExecuted) data = $('No URLs to Fetch').first().json;
if (!data) throw new Error('No data received from either research path');
const run = data.run || {};
if (run.dryRun && run.forceFailAt === 'agent2') throw new Error('Forced test failure in Agent 2 (dry run, on purpose)');
const topic = data.topic, sourceContent = data.sourceContent || '', sourceUrl = data.sourceUrl || '';
const snippets = data.snippets || [], fetched = data.fetchedContent || [];
const sources = [];
if (sourceUrl && sourceContent.length > 100) sources.push({ url: sourceUrl, title: topic });
for (const s of (data.sources || [])) if (s && s.url && !sources.some(x => x.url === s.url)) sources.push(s);
if (sourceContent.length <= 100 && !snippets.length && !fetched.length)
  throw new Error('No research material: the source page and the search both came back empty');
// Sized for qwq's 16k context: about 12,000 characters of research in total.
let r = `# Research on: ${topic}\n\n`;
if (sourceContent.length > 100) r += `## Primary source\nSource: ${sourceUrl}\n\n${sourceContent.slice(0, 5000)}\n\n`;
if (snippets.length) r += `## Search result summaries\n\n` + snippets.map((s, i) => `${i + 1}. ${s}`).join('\n\n') + '\n\n';
for (const [i, f] of fetched.entries()) r += `## Source ${i + 1}: ${f.url}\n\n${String(f.content).slice(0, 2200)}\n\n`;
if (r.length > 12000) r = r.slice(0, 12000) + '\n\n[research truncated]';
console.log('Agent 2: research', r.length, 'chars | primary:', sourceContent.length > 100, '| snippets:', snippets.length, '| fetched:', fetched.length, '| sources:', sources.length);
return [{ json: { researchSummary: r, sources, topic, style: data.style, length: data.length, angle: data.angle, run } }];
